INSERT INTO public.allowed_emails (email, full_name, role, is_active, added_by)
SELECT email, full_name, role, is_active, added_by
FROM seed_data
ON CONFLICT (email) DO UPDATE
SET 
  full_name = CASE 
    WHEN allowed_emails.role = 'admin' AND allowed_emails.full_name IS NOT NULL THEN allowed_emails.full_name 
    ELSE EXCLUDED.full_name 
  END,
  is_active = true;